  @LocalServerPort int port;

  @Test
  void documentsAllOperationsAndRequestContracts() throws Exception {
    var request = HttpRequest.newBuilder(URI.create("http://localhost:" + port + "/api/openapi")).build();
    var response = HttpClient.newHttpClient().send(request, HttpResponse.BodyHandlers.ofString());
    assertEquals(200, response.statusCode(), response.body());
    JsonNode spec = JsonMapper.shared().readTree(response.body());
    JsonNode paths = spec.path("paths");
    Map<String, Set<String>> expected = Map.of(
        "/api/courts", Set.of("get", "post"),
        "/api/courts/{id}", Set.of("get", "put", "patch", "delete"),
        "/api/surfaces", Set.of("get", "post"),
        "/api/surfaces/{id}", Set.of("get", "put", "patch", "delete"),
        "/api/reservations", Set.of("get", "post"),
        "/api/reservations/{id}", Set.of("get", "put", "patch", "delete"),
        "/api/courts/{courtNumber}/reservations", Set.of("get"));
    assertEquals(expected.size(), paths.size());
    expected.forEach((path, methods) -> {
      JsonNode item = paths.path(path);
      assertEquals(methods.size(), item.size(), path);
      methods.forEach(method -> {
        JsonNode operation = item.path(method);
        assertFalse(operation.path("summary").asString("").isBlank(), path + " " + method);
        assertTrue(operation.path("responses").has(method.equals("post") ? "201" : method.equals("delete") ? "204" : "200"), path + " " + method);
      });
    });
    JsonNode schemas = spec.path("components").path("schemas");
    assertTrue(schemas.path("Court").path("required").toString().contains("surfaceId"));
    assertTrue(schemas.path("CourtPatch").path("properties").has("surfaceId"));
    assertFalse(schemas.path("CourtPatch").has("required"));
