    assertTrue(schemas.path("ReservationPatch").path("description").asString().contains("supplied together"));
    assertTrue(paths.path("/api/reservations").path("get").path("parameters").toString().contains("futureOnly"));
    assertTrue(paths.path("/api/courts/{id}").path("delete").path("responses").has("409"));
  }
}
